// This is a fixed-color (non-addressable) 12V strip - switch/dim it through a logic-level MOSFET, gated by PWM pin 9 on Arduino Uno. A GPIO pin cannot drive the strip directly (wrong voltage, not enough current).
#define MOSFET_GATE_PIN 9

void setup() {
 pinMode(MOSFET_GATE_PIN, OUTPUT);
}

void loop() {
 for (int b = 0; b = 0; b -= 5) { analogWrite(MOSFET_GATE_PIN, b); delay(20); } // fade out
}",

